// The ZZF2L case database, generated from the ZZF2L Cases sheet (one tab per
// slot; `gid` is the tab). Positions are cubie names in the trainer's frame
// (white down): a corner is 'UFR' / 'DFL' with its white sticker facing up/down
// ('ud'), right/left ('rl') or front/back ('fb'); an edge is 'UF' / 'FR'.
// `lookup` maps every position the pair can be in ('UFL-rl|UF') to the case
// and the AUF that turns it into the case's canonical picture. `cmap` / `emap`
// say which colour (as a face letter) each sticker of the placed piece shows.
// Kept as one literal so the app needs no JSON import; regenerate, do not edit.

export type SlotName = 'FR' | 'FL' | 'BR' | 'BL';
/** Which way the corner's white sticker faces. */
export type CornerOrient = 'ud' | 'rl' | 'fb';

export interface F2LCase {
  n: number;
  section: 'Last slot' | 'Edge in slot' | 'Corner in slot' | 'Both in slot';
  /** the corner's cubie name in the canonical picture ('UFR', 'DFR', 'DFL'...) */
  corner: string;
  co: CornerOrient;
  /** the edge's cubie name ('UR', 'FL'...) */
  edge: string;
  /** the sheet's algs, a leading (U) is the AUF */
  algs: string[];
  /** algs that use other slots, which must be empty or solved */
  others: { alg: string; free: SlotName[] }[];
  note: string;
  /** the R/L/U-only alg shown by default: from the sheet, or found by search */
  simple: string;
  simple_src: 'sheet' | 'search';
}

export interface LookupHit {
  n: number;
  /** '' | 'U' | "U'" | 'U2': added to the alg's own AUF */
  auf: string;
}

export interface SlotData {
  cases: Record<string, F2LCase>;
  lookup: Record<string, LookupHit>;
  /** 'UFR-fb' -> face the sticker is on -> the colour it shows (as a face letter) */
  cmap: Record<string, Record<string, string>>;
  /** 'UF' -> face -> colour letter */
  emap: Record<string, Record<string, string>>;
  /** the sheet tab (the URL's gid) */
  gid: string;
  covered: number;
}

export interface F2LData {
  slots: Record<SlotName, SlotData>;
}

